extends Camera3D
## Third-person chase camera: fixed world-axis offset behind and above the robot, smoothed.

@export var target_path: NodePath
@export var offset := Vector3(0.0, 5.5, 6.0)
@export var smoothing := 6.0

var _target: Node3D


func _ready() -> void:
	_target = get_node_or_null(target_path)
	snap()


func snap() -> void:
	if _target:
		global_position = _target.global_position + offset
		look_at(_target.global_position + Vector3(0, 0.6, 0), Vector3.UP)


func _process(delta: float) -> void:
	if _target == null:
		return
	var desired := _target.global_position + offset
	global_position = global_position.lerp(desired, 1.0 - exp(-smoothing * delta))
	look_at(_target.global_position + Vector3(0, 0.6, 0), Vector3.UP)

